import{_ as t,o as e,c as i,a2 as r}from"./chunks/framework.Ky-Ipuyb.js";const u=JSON.parse('{"title":"ImGui 가이드","description":"","frontmatter":{"lang":"ko","sourcePath":"docs/imgui/README.ko.md"},"headers":[],"relativePath":"ko/imgui/index.md","filePath":"ko/imgui/index.md"}'),s={name:"ko/imgui/index.md"};function o(d,a,l,n,h,p){return e(),i("div",null,[...a[0]||(a[0]=[r(`<h1 id="imgui-가이드" tabindex="-1">ImGui 가이드 <a class="header-anchor" href="#imgui-가이드" aria-label="Permalink to &quot;ImGui 가이드&quot;">​</a></h1><p>sfml.js-imgui로 SFML 창에 디버그 패널, 장면 검사기, 네이티브 편집 도구를 만듭니다. 첫 프레임 루프에서 시작해 상태 편집, 테이블, 텍스트 입력, 폰트, 사용자 지정 렌더링을 추가합니다.</p><p>현재 소스는 Dear ImGui 1.91.9b와 imgui-sfml 3.0을 대상으로 하며 예제는 JavaScript와 SFML 3.1 API를 사용합니다. JavaScript와 <a href="/ko/guide/window">SFML 창</a>의 기초가 필요하고 C++ 지식은 필요하지 않습니다.</p><h2 id="학습-순서" tabindex="-1">학습 순서 <a class="header-anchor" href="#학습-순서" aria-label="Permalink to &quot;학습 순서&quot;">​</a></h2><table tabindex="0"><thead><tr><th>장</th><th>배우거나 만드는 것</th></tr></thead><tbody><tr><td><a href="/ko/imgui/getting-started">빠른 시작</a></td><td>완전한 카운터, 프레임 수명, 입력 캡처, 안전한 종료</td></tr><tr><td><a href="/ko/imgui/widgets">위젯과 상태</a></td><td>지속 상태, 고유 ID, 실시간 장면 검사기</td></tr><tr><td><a href="/ko/imgui/layout">레이아웃</a></td><td>테이블, 메뉴, 확인 모달, 범위 짝</td></tr><tr><td><a href="/ko/imgui/callbacks">텍스트와 콜백</a></td><td>UTF-8 편집, 계약, 목록 getter, 그래프</td></tr><tr><td><a href="/ko/imgui/fonts">폰트와 스타일</a></td><td>아틀라스, CJK, 간격, 색, DPI</td></tr><tr><td><a href="/ko/imgui/rendering">렌더링과 여러 창</a></td><td>장면 합성, 그리기 목록, 창별 소유권</td></tr><tr><td><a href="/ko/imgui/api">API 가이드</a></td><td>정확한 시그니처, 오버로드, 수명 확인</td></tr></tbody></table><p>실습 장마다 완전한 실행 소스를 연결하고 짧은 코드의 삽입 위치와 기대 결과를 설명합니다. 영어·중국어·일본어·한국어를 제공합니다.</p><h2 id="실행-예제-선택" tabindex="-1">실행 예제 선택 <a class="header-anchor" href="#실행-예제-선택" aria-label="Permalink to &quot;실행 예제 선택&quot;">​</a></h2><p>monorepo 루트에서 bootstrap을 한 번 실행한 뒤 예제를 시작합니다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/bootstrap.cjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-imgui/examples/demo.cjs</span></span></code></pre></div><ul><li><a href="/ko/examples/imgui#demo">위젯 데모</a>: Dear ImGui 기본 위젯과 레이아웃 탐색.</li><li><a href="/ko/examples/imgui#scene-inspector">장면 검사기</a>: 움직이는 원의 크기·색·속도 편집.</li><li><a href="/ko/examples/imgui#workbench">workbench</a>: 텍스트·선택·테이블·모달·시간 그래프 조합.</li></ul><h2 id="패키지-역할" tabindex="-1">패키지 역할 <a class="header-anchor" href="#패키지-역할" aria-label="Permalink to &quot;패키지 역할&quot;">​</a></h2><p>ImGui는 위젯·열거 값·콜백 래퍼·네이티브 핸들 연산을 제공합니다. SFML은 창 연동·이벤트 전달·프레임 제출을 맡습니다. getFontAtlas와 getStyleColors는 최상위 export입니다.</p><p>앱 값은 JavaScript가 소유하고 쓰기 가능한 네이티브 스칼라는 타입 배열로 전달합니다. IO·스타일 뷰·폰트·그리기 목록에는 네이티브 소유자와 유효 기간이 있습니다. 각 장에서 경계를 설명하며 정확한 계약은 <a href="/ko/reference/imgui/" target="_self">API 레퍼런스</a>에서 확인합니다.</p>`,13)])])}const c=t(s,[["render",o]]);export{u as __pageData,c as default};
